mapper.select:
SELECT g4.id, g4.type, g1.name as firstDimensionName, g1.NAME_EN as firstDimensionNameEn, g1.code as firstDimensionCode, g1.id as firstId, g2.name as secondDimensionName, g2.NAME_EN as secondDimensionNameEn, g2.code as secondDimensionCode, g2.id as secondId, g3.name as thirdDimensionName, g3.NAME_EN as thirdDimensionNameEn, g3.code as thirdDimensionCode, g3.id as thirdId, g4.name, g4.NAME_EN as nameEn, g4.code as code, g4.enable as enable, g4.source, g4.association_status as associationStatus, g4.description, g4.label_type as labelType, g4.client_id as clientId, g4.create_time FROM ins_tag_client g4 LEFT JOIN ins_tag_client g3 ON g4.parent_id=g3.ID LEFT JOIN ins_tag_client g2 ON g3.parent_id=g2.ID LEFT JOIN ins_tag_client g1 ON g2.parent_id=g1.ID WHERE 1=1 AND g1.CODE IS NOT NULL
AND g4.client_id = #{model.clientId}
AND g4.type = #{model.type}
AND g4.type in
#{item}
AND g4.enable = #{model.enable}
AND g1.code in
#{item}
AND g4.NAME LIKE CONCAT('%', #{model.name} ,'%')
order by ${model.order}
order by create_time desc

select t.tag_id as tagId, t.client_id as clientId, t1.full_name as fullName, t1.abbreviation as abbreviation, t1.code from ins_tag_client t left join ins_customer_info t1 on t.client_id = t1.id where t.enable=1
AND t.tag_id in
#{item}
